	// clusterSession.
	sess.authContext.teleportCluster.isRemoteClosed = func() bool { return true }
	c.Assert(f.getClusterSession(ctx), check.IsNil)
	_, ok := f.clusterSessions.Get(ctx.key())
	c.Assert(ok, check.Equals, false)
}

