func (t *trackingConn) GetClientLastActive() time.Time {
	t.RLock()
	defer t.RUnlock()
	return t.lastActive
}

// UpdateClientActivity sets last recorded client activity
func (t *trackingConn) UpdateClientActivity() {
	t.Lock()
	defer t.Unlock()
	t.lastActive = t.clock.Now().UTC()
}

func (f *Forwarder) getOrCreateClusterSession(ctx authContext) (*clusterSession, error) {
	return f.newClusterSession(ctx)
}

type userCredentials struct {
	tlsConfig *tls.Config
	notAfter  time.Time
}

func (f *Forwarder) now() time.Time {
	if f.Clock != nil {
		return f.Clock.Now()
	}
	return time.Now()
}

func (f *Forwarder) getUserCredentials(ctx authContext) *tls.Config {
	f.Lock()
	defer f.Unlock()
	if f.userCredentials == nil {
		return nil
	}
	value, ok := f.userCredentials.Get(ctx.key())
	if !ok {
		return nil
	}
	creds := value.(*userCredentials)
	if f.now().Add(time.Minute).After(creds.notAfter) {
		f.userCredentials.Remove(ctx.key())
		return nil
	}
	return creds.tlsConfig
}


// getOrRequestCertificate shares only the user certificate across requests.
// Each request still gets its own cluster session, dialer and forwarding state.
func (f *Forwarder) getOrRequestCertificate(ctx authContext) (*tls.Config, error) {
	forwarderCtx := f.ctx
	if forwarderCtx == nil {
		forwarderCtx = context.Background()
	}
	for {
		if creds := f.getUserCredentials(ctx); creds != nil {
			return creds, nil
		}
		requestCtx, finish := f.getOrCreateRequestContext(ctx.key())
		if finish == nil {
			select {
			case <-requestCtx.Done():
				continue
			case <-forwarderCtx.Done():
				return nil, trace.BadParameter("forwarder is closing, aborting the request")
			}
		}

		// A previous request may have filled the cache between our first lookup
		// and our turn as the active requester.
		if creds := f.getUserCredentials(ctx); creds != nil {
			finish()
			return creds, nil
		}
		creds, err := f.requestCertificate(ctx)
		if err == nil {
			err = f.setUserCredentials(ctx, creds)
		}
		finish()
		return creds, trace.Wrap(err)
	}
}

func (f *Forwarder) setUserCredentials(ctx authContext, tlsConfig *tls.Config) error {
	if len(tlsConfig.Certificates) == 0 || len(tlsConfig.Certificates[0].Certificate) == 0 {
		return trace.BadParameter("Kubernetes client certificate is missing")
	}
	cert, err := x509.ParseCertificate(tlsConfig.Certificates[0].Certificate[0])
	if err != nil {
		return trace.Wrap(err)
	}
	now := f.now()
	if now.Add(time.Minute).After(cert.NotAfter) {
		return trace.BadParameter("Kubernetes client certificate expires in less than one minute")
	}

	ttl := cert.NotAfter.Sub(now.Add(time.Minute))
	if ctx.sessionTTL > 0 && ctx.sessionTTL < ttl {
		ttl = ctx.sessionTTL
	}
	// ttlmap has a one-second minimum. Retrieval checks NotAfter again so a
	// certificate near the one-minute boundary is never reused past it.
	if ttl < time.Second {
		ttl = time.Second
	}
	f.Lock()
	defer f.Unlock()
	if f.userCredentials == nil {
		cacheClock := f.Clock
		if cacheClock == nil {
			cacheClock = clockwork.NewRealClock()
		}
		f.userCredentials, err = ttlmap.New(defaults.ClientCacheSize, ttlmap.Clock(cacheClock))
		if err != nil {
			return trace.Wrap(err)
		}
	}
	return trace.Wrap(f.userCredentials.Set(ctx.key(), &userCredentials{tlsConfig: tlsConfig, notAfter: cert.NotAfter}, ttl))
}

