func (s ForwarderSuite) TestCredentialCacheAndRequestSessions(c *check.C) {
	userCredentials, err := ttlmap.New(defaults.ClientCacheSize)
	c.Assert(err, check.IsNil)
	csrClient, err := newMockCSRClient()
	c.Assert(err, check.IsNil)
	client := &countingCSRClient{mockCSRClient: csrClient}
	f := &Forwarder{
		ForwarderConfig: ForwarderConfig{
			Keygen:     testauthority.New(),
			AuthClient: client,
			Clock:      clockwork.NewRealClock(),
		},
		userCredentials: userCredentials,
		activeRequests:  make(map[string]context.Context),
		ctx:             context.Background(),
		log:             logrus.New(),
	}

	user, err := services.NewUser("bob")
	c.Assert(err, check.IsNil)
	ctx := authContext{
		teleportCluster: teleportClusterClient{
			isRemote:   true,
			name:       "site a",
			remoteAddr: *utils.MustParseAddr("first.example.com"),
		},
		Context: auth.Context{
			User:     user,
			Identity: auth.WrapIdentity(tlsca.Identity{Username: "bob"}),
		},
		sessionTTL: time.Hour,
	}
	type certResult struct {
		config *tls.Config
		err    error
	}
	const concurrentRequests = 10
	results := make(chan certResult, concurrentRequests)
	for i := 0; i < concurrentRequests; i++ {
		go func() {
			config, err := f.getOrRequestCertificate(ctx)
			results <- certResult{config: config, err: err}
		}()
	}
	var cached *tls.Config
	for i := 0; i < concurrentRequests; i++ {
		result := <-results
		c.Assert(result.err, check.IsNil)
		if cached == nil {
			cached = result.config
		} else {
			c.Assert(result.config, check.Equals, cached)
		}
	}
	c.Assert(client.requestCount(), check.Equals, 1)
	c.Assert(f.userCredentials.Len(), check.Equals, 1)

	firstSession, err := f.getOrCreateClusterSession(ctx)
	c.Assert(err, check.IsNil)
	ctx.teleportCluster.remoteAddr = *utils.MustParseAddr("second.example.com")
	secondSession, err := f.getOrCreateClusterSession(ctx)
	c.Assert(err, check.IsNil)
	c.Assert(firstSession, check.Not(check.Equals), secondSession)
	c.Assert(firstSession.teleportCluster.remoteAddr.Addr, check.Equals, "first.example.com")
	c.Assert(secondSession.teleportCluster.remoteAddr.Addr, check.Equals, "second.example.com")
	c.Assert(firstSession.tlsConfig, check.Equals, secondSession.tlsConfig)
	c.Assert(client.requestCount(), check.Equals, 1)

	// A new client login must not reuse credentials from the old certificate.
	newLogin := ctx
	newLogin.clientCertExpires = time.Now().Add(time.Hour)
	_, err = f.getOrRequestCertificate(newLogin)
	c.Assert(err, check.IsNil)
	c.Assert(client.requestCount(), check.Equals, 2)

	// Certificates with less than one minute remaining cannot be reused or cached.
	f.Clock = clockwork.NewFakeClockAt(csrClient.lastCert.NotAfter.Add(-30 * time.Second))
	_, err = f.getOrRequestCertificate(newLogin)
	c.Assert(err, check.NotNil)
	c.Assert(client.requestCount(), check.Equals, 3)
}

